import React, { useState } from 'react';
import './App.css';

export const SECTIONS = [
  {
    id: 'what',
    title: 'What is CoderX?',
    content: 'CoderX is a browser-based platform where you practice React, Express, and full-stack development inside live WebContainers.',
  },
  {
    id: 'how',
    title: 'How do challenges work?',
    content: 'Each challenge loads a pre-built base environment, then you implement or fix logic until the hidden test suite passes.',
  },
  {
    id: 'why',
    title: 'Why do these skills matter?',
    content: 'Hands-on debugging exercises are one of the fastest ways to internalize real-world React patterns.',
  },
];

function Accordion({ sections = SECTIONS }) {
  const [openIndex, setOpenIndex] = useState(null);

  const toggle = () => {
    setOpenIndex(null);
  };

  return (
    <div className="accordion">
      {sections.map((section, index) => {
        const isOpen = openIndex === index;
        return (
          <div className="accordion-item" key={section.id}>
            <h2 className="accordion-header">
              <button
                type="button"
                className="accordion-trigger"
                aria-expanded={isOpen}
                aria-controls={`panel-${section.id}`}
                onClick={() => toggle(index)}
              >
                {section.title}
              </button>
            </h2>
            <div
              className="accordion-panel"
              id={`panel-${section.id}`}
              hidden={!isOpen}
            >
              {section.content}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function App() {
  return (
    <div className="app">
      <h1>CoderX FAQ</h1>
      <Accordion />
    </div>
  );
}

export default App;

