* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  background: #f4f5f9;
  color: #1f2430;
}

.app {
  max-width: 640px;
  margin: 48px auto;
  padding: 0 16px;
}

.app h1 {
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.accordion {
  background: #ffffff;
  border: 1px solid #dde1ea;
  border-radius: 10px;
  overflow: hidden;
}

.accordion-item {
  border-bottom: 1px solid #dde1ea;
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-header {
  margin: 0;
}

.accordion-trigger {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 14px 18px;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: inherit;
  background: transparent;
  border: none;
  cursor: pointer;
}

.accordion-trigger:hover,
.accordion-trigger:focus-visible {
  background: #eef1f7;
}

.accordion-trigger[aria-expanded='false']::after {
  content: '+';
  color: #5b6478;
  font-weight: 400;
}

.accordion-trigger[aria-expanded='true']::after {
  content: '\2212';
  color: #5b6478;
  font-weight: 400;
}

.accordion-panel {
  padding: 4px 18px 16px;
  color: #4c5468;
  line-height: 1.55;
}

