import { describe, test, expect } from 'vitest';
import { render, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App, { SECTIONS } from '../src/App';

const getTriggers = (container) =>
  Array.from(container.querySelectorAll('.accordion-trigger'));

const getPanel = (container, sectionId) =>
  container.querySelector(`#panel-${sectionId}`);

describe('Accordion component', () => {
  test('renders a trigger button for every section header', () => {
    const { container } = render(<App />);
    const triggers = getTriggers(container);
    if (triggers.length !== SECTIONS.length) {
      throw new Error(`Expected ${SECTIONS.length} triggers, got ${triggers.length}`);
    }
    SECTIONS.forEach((section) => {
      if (!triggers.some((t) => t.textContent.includes(section.title))) {
        throw new Error(`Missing trigger for "${section.title}"`);
      }
    });
  });

  test('all panels start collapsed', () => {
    const { container } = render(<App />);
    SECTIONS.forEach((section) => {
      const panel = getPanel(container, section.id);
      if (!panel) throw new Error(`Missing panel for "${section.title}"`);
      if (!panel.hidden) {
        throw new Error(`Panel "${section.id}" should start collapsed`);
      }
    });
  });

  test('clicking a header expands its panel', () => {
    const { container } = render(<App />);
    const trigger = getTriggers(container)[0];
    fireEvent.click(trigger);
    const panel = getPanel(container, SECTIONS[0].id);
    if (panel.hidden) {
      throw new Error('Panel should be expanded after clicking its header');
    }
  });

  test('clicking an open header collapses it again', () => {
    const { container } = render(<App />);
    const trigger = getTriggers(container)[0];
    fireEvent.click(trigger);
    fireEvent.click(trigger);
    const panel = getPanel(container, SECTIONS[0].id);
    if (!panel.hidden) {
      throw new Error('Panel should collapse after clicking its open header');
    }
  });

  test('opening a section auto-closes the previously open one', () => {
    const { container } = render(<App />);
    const triggers = getTriggers(container);
    fireEvent.click(triggers[0]);
    fireEvent.click(triggers[1]);
    const firstPanel = getPanel(container, SECTIONS[0].id);
    const secondPanel = getPanel(container, SECTIONS[1].id);
    if (!firstPanel.hidden) {
      throw new Error('First panel should close when a second section is opened');
    }
    if (secondPanel.hidden) {
      throw new Error('Second panel should be open after clicking its header');
    }
  });

  test('aria-expanded reflects the open state of each trigger', () => {
    const { container } = render(<App />);
    const triggers = getTriggers(container);
    triggers.forEach((t) => {
      if (t.getAttribute('aria-expanded') !== 'false') {
        throw new Error('All triggers should start with aria-expanded="false"');
      }
    });
    fireEvent.click(triggers[0]);
    if (triggers[0].getAttribute('aria-expanded') !== 'true') {
      throw new Error('Open trigger should report aria-expanded="true"');
    }
    triggers.slice(1).forEach((t) => {
      if (t.getAttribute('aria-expanded') !== 'false') {
        throw new Error('Closed triggers should report aria-expanded="false"');
      }
    });
  });
});
